t// create\r\n\t\tfor (int i = 0; i < NumTasks; ++i)\r\n\t\t{\r\n\t\t\tTasks[i] = \r\n\t\t\t  MakeUnique<FAsyncTask<FCountActiveRobotsTask>>(StepSize * i, StepSize, Counts[i]);\r\n\t\t}\r\n\t\t// launch\r\n\t\tfor (int i = 0; i < NumTasks; ++i)\r\n\t\t{\r\n\t\t\tTasks[i]->StartBackgroundTask();\r\n\t\t}\r\n\t\t// wait\r\n\t\tfor (int i = 0; i < NumTasks; ++i)\r\n\t\t{\r\n\t\t\tTasks[i]->EnsureCompletion(true, true);\r\n\t\t}\r\n\r\n\t\tCount = std::accumulate(Counts.begin(), Counts.end(), 0);\r\n\t}\r\n}\n"})}),"\n",(0,a.jsx)(t.p,{children:"In this code we:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"allocate 4 background task objects which will run on background threads"}),"\n",(0,a.jsx)(t.li,{children:"divide the array of robots into 4 sections and pass each task the start and length of their section"}),"\n",(0,a.jsx)(t.li,{children:"allocate an array of 4 int32 objects, each task accumulates their count into one element of this array"}),"\n",(0,a.jsx)(t.li,{children:"after all the threads are finished we accumulate the 4 count objects into one value"}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Now we get these timings:"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"offset",src:n(64712).A+"",width:"439",height:"346"})}),"\n",(0,a.jsx)(t.p,{children:"Running on four background threads takes 4 times longer than running on one.  What is happening\r\nhere is an issue of cache coherency and false sharing."}),"\n",(0,a.jsx)(t.p,{children:"Here is the diagram of the cache layout on a Ryzen 8 core CPU again:"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{src:n(99942).A+"",width:"1920",height:"1080"})}),"\n",(0,a.jsxs)(t.p,{children:["We see that each core has its own L1 and L2 cache.  When a value is in main memory\r\neach CPU core that refers to that value has its own copy of that value in its L1 cache.  Cache\r\ncoherency is the mechanism by which changes to these cached values are synchronized - typically\r\nby using a protocol like ",(0,a.jsx)(t.a,{href:"https://en.wikipedia.org/wiki/MESI_protocol",children:"MISE"}),"."]}),"\n",(0,a.jsx)(t.p,{children:"When one core changes a value in its cache, that value becomes invalid in every other core's cache which holds that value, and\r\nthe next time one of those other cores accesses that value it is copied from the cache of the core\r\nwhich changed it.  This mechanism make sure all the cores only ever see the same\r\nvalue, which make programming much easier, but it does mean that operations on the second core are stalled while value is\r\nretrieved from the core which changed it."}),"\n",(0,a.jsx)(t.p,{children:"The MISE protocol which synchronizes values between cores does not work by copying individual\r\nvalues between core - it copies whole cache lines at a time."}),"\n",(0,a.jsx)(t.p,{children:'Why we see a problem here, causing the multithreaded implementation to be so much slower, is not that\r\nwe are updating the same value, but that the each thread is updating a value\r\nin the Counts array and all those values are on the same cache line.  This problem\r\nis referred to as "false sharing" because  while the threads are not actually sharing\r\ncount values, synchronizing the core caches using whole cache lines makes it appear as if they were.'}),"\n",(0,a.jsx)(t.p,{children:"This problem can be fixed in a number of ways:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"we could give each task its own Count value to accumulate to accumulate into and only\r\nupdate the Count array once at the end"}),"\n",(0,a.jsx)(t.li,{children:"we could make the Count array 16 times as large and have each thread\r\nuse every 16th value - this would ensure that the used values are more 64 bytes apart\r\nso they are not on the cache line"}),"\n",(0,a.jsx)(t.li,{children:"we could accumulate the values into property in a structure which was padded to be\r\n64 bytes long, so that the values are not on the same cache line, like:"}),"\n"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-cpp",children:"struct PaddedValue\r\n{\r\n\tint32 Value = 0;\r\n\tchar Padding[ 64-sizeof(int32)];\r\n};\n"})}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"we could accumulate the values into property in a structure which was aligned\r\nto 64 bytes long, so that the values are not on the same cache line, like:"}),"\n"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-cpp",children:"struct alignas(64) AlignedValue\r\n{\r\n\tint32 Value = 0;\r\n};\n"})}),"\n",(0,a.jsx)(t.p,{children:"The code to accumulate into a local variable looks like this:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-cpp",children:"class FCountActiveRobotsTaskLocalCount : public FNonAbandonableTask\r\n{\r\npublic:\r\n\tFCountActiveRobotsTaskLocalCount(const int32 InStart, const int32 InNum, int32& InCount)\r\n\t\t: Start(InStart), Num(InNum), Count(InCount)\r\n\t{\r\n\t}\r\n\r\n\tvoid DoWork()\r\n\t{\r\n\t\tint32 LocalCount = 0;\r\n\t\tfor (int i = Start; i < Start + Num; ++i)\r\n\t\t{\r\n\t\t\tif (Robots.Actives[i])\r\n\t\t\t{\r\n\t\t\t\tLocalCount++;\r\n\t\t\t}\r\n\t\t}\r\n\t\tCount = LocalCount;\r\n\t}\r\n\r\n\tTStatId GetStatId() const { return TStatId(); }\r\nprivate:\r\n\tint32 Start;\r\n\tint32 Num;\r\n\tint32& Count;\r\n};\n"})}),"\n",(0,a.jsx)(t.p,{children:"and the code to pad the Counts array and only use every 16th element looks like this:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-cpp",children:"void Count_Robots_Background_Threads_Padding()\r\n{\r\n\tint32 Count = 0;\r\n\tTRACE_CPUPROFILER_EVENT_SCOPE(Count_Robots_Background_Threads_Padding)\r\n\t{\r\n\t\tconstexpr int NumTasks = 4;\r\n\t\tstd::array<int32, NumTasks * 16 > Counts;\r\n\t\tstd::fill(Counts.begin(), Counts.end(), 0);\r\n\t\tstd::array< TUniquePtr< FAsyncTask<FCountActiveRobotsTask> >, NumTasks > Tasks;\r\n\r\n\t\tint32 StepSize = Robots.Actives.Num() / NumTasks;\r\n\r